def find_bridges(n: int, edges: list[tuple[int, int]]) -> list[tuple[int, int]]:
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    low = [0] * n
    disc = [-1] * n
    bridges = []

    def dfs(u, parent):
        nonlocal time
        time += 1
        low[u] = disc[u] = time
        for v in graph[u]:
            if disc[v] == -1:
                dfs(v, parent)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.append((u, v))
            elif v != parent:
                low[u] = min(low[u], disc[v])

    time = 0
    for u in range(n):
        if disc[u] == -1:
            dfs(u, -1)

