    if n == 0:
        return "0"

    result = []
    while n != 0:
        remainder = n % 3
        n //= 3

        if remainder == 2:
            result.append('-')
            n += 1
        elif remainder == 1:
            result.append('+')
        else:
            result.append('0')

    return ''.join(result[::-1])
