def rolling_variance(nums: list[float], k: int) -> list[float]:
    if k <= 0 or k > len(nums):
        return []
    else:
        means = [sum(nums[:k])/k] * (len(nums)-k+1)
        squared_diffs = [sum((x-means[i])**2 for x in nums[i:i+k]) for i in range(len(nums)-k+1)]
        variances = [squared_diffs[i]/k for i in range(len(squared_diffs))]
        return [round(variances[i], 3) for i in range(len(variances))]
