from collections import defaultdict

def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []
    graph = defaultdict(list)
    for a, b in pairs:
        graph[a].append(b)
    visited = [0]*n
    stack = []
    for i in range(n):
        if visited[i] == 0:
            if not dfs(i, visited, stack, graph):
                return []
    stack.reverse()
    return stack

def dfs(node, visited, stack, graph):
    visited[node] = 1
    for neighbor in graph[node]:
        if visited[neighbor] == 1:
            return False
        if visited[neighbor] == 0:
            if not dfs(neighbor, visited, stack, graph):
                return False
    visited[node] = 2
    stack.append(node)
    return True
```

