def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    # Create a blocked set for faster lookup
    blocked_set = set(blocked)

    # Define a helper function to check if a position is blocked
    def is_blocked(pos):
        return pos in blocked_set

    # Define a helper function to check if a position is under attack
    def is_attacked(i, j):
        # Check if there is a queen in the same row or column
        for k in range(n):
            if (i == k) or (j == k) or (i - j == k - j) or (i + j == k + j):
                return True
        return False

    # Define the main function to count the number of placements
    def count_placements(i=0):
        if i == n:
            return 1
        count = 0
        for j in range(n):
            if not is_attacked(i, j) and not is_blocked((i, j)):
                count += count_placements(i + 1)
        return count

