from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = (-1, -1), (-1, -1)
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)
    if start == (-1, -1) or end == (-1, -1):
        return -1

    # Directions: up, down, left, right
    dirs = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    # Queue for BFS, each element is a tuple (position, number of breaks)
    queue = deque([(start, 0)])
    # Set to keep track of visited cells
    visited = set([(start, 0)])

    while queue:
        pos, breaks = queue.popleft()
        if pos == end:
            return breaks
        for d in dirs:
            ni, nj = pos[0] + d[0], pos[1] + d[1]
            if 0 <= ni < rows and 0 <= nj < cols:
                if grid[ni][nj] == '#':
                    # If we have not broken any wall yet, break it and add to queue
                    if (ni, nj) not in visited or (ni, nj) in visited and visited[(ni, nj)] > breaks + 1:
                        visited[(ni, nj)] = breaks + 1
                        queue.append(((ni, nj), breaks + 1))
                elif grid[ni][nj] == '.':
                    # If we have not visited this cell yet, add to queue
                    if (ni, nj) not in visited or (ni, nj) in visited and visited[(ni, nj)] > breaks:
                        visited[(ni, nj)] = breaks
                        queue.append(((ni, nj), breaks))
    return -1
