def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = (-1, -1), (-1, -1)
    wall_coords = []
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
