            elif grid[i][j] == 'E':
                end = (i, j)
            elif grid[i][j] == '#':
                wall_coords.append((i, j))

    if start == (-1, -1) or end == (-1, -1):
        return -1

    moves = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    visited = set()
    queue = deque([(start, 0, 0)])  # (coords, remaining breaks, steps)
    while queue:
        (x, y), breaks, steps = queue.popleft()
        if (x, y) == end:
            return steps
        for dx, dy in moves:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and (nx, ny) not in visited:
