def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    queue = deque([(source, 0)])
    visited = [0] * n
    shortest_paths = [0] * n
    shortest_paths[source] = 1

    while queue:
        node, path_length = queue.popleft()
        if node == target:
            return shortest_paths[target]
        for neighbor in graph[node]:
            if visited[neighbor] < path_length + 1:
                queue.append((neighbor, path_length + 1))
                visited[neighbor] = path_length + 1
                shortest_paths[neighbor] = shortest_paths[node]

    return 0 if target != source else 1

