def seating_arrangements(guests: list[str], conflicts: list[tuple[str, str]]) -> list[list[str]]:
    conflicts_dict = {guest: set() for guest in guests}
    for conflict in conflicts:
        conflicts_dict[conflict[0]].add(conflict[1])
        conflicts_dict[conflict[1]].add(conflict[0])

    arrangements = []
    def backtrack(start_index, current_arrangement):
        if start_index == len(guests):
            arrangements.append(current_arrangement[:])
            return

        for i in range(start_index, len(guests)):
            if all(guests[i] not in conflicts_dict[guest] for guest in current_arrangement):
                current_arrangement.append(guests[i])
                backtrack(i + 1, current_arrangement)
                current_arrangement.pop()

    backtrack(0, [])
    return sorted(arrangements)
```

