def is_local_redirect(target: str, host: str) -> bool:
    if any(ord(c) < 32 or ord(c) > 127 for c in target):
        return False
    if target.startswith('/') and not target.find('/') > 1:
        return True
    if target.lower().startswith('http://') or target.lower().startswith('https://'):
        import re
        url_match = re.search('(?P<url>https?://[^/]+)(?P<path>/?.*)', target, re.I)
        if url_match:
            url_host = url_match.group('url').lower().replace('http://', '').replace('https://', '').split('/')[0]
            return url_host == host.lower()
    return False
