from datetime import datetime, timedelta

def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    date_format = "%Y-%m-%d"
    start_date = datetime.strptime(start, date_format)
    holidays = [datetime.strptime(date, date_format) for date in holidays]

    if n == 0:
        return start

    if n > 0:
        while n > 0:
            start_date += timedelta(days=1)
            weekday = start_date.weekday()
            if weekday < 5 and start_date not in holidays:
                n -= 1
    else:
        while n < 0:
            start_date -= timedelta(days=1)
            weekday = start_date.weekday()
            if weekday < 5 and start_date not in holidays:
                n += 1

    return start_date.strftime(date_format)
