import ast

def matches_filter(expression: str, record: dict) -> bool:
    # Define the operators and their corresponding functions
    operators = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
                 ast.Div: operator.truediv, ast.USub: operator.neg,
                 ast.BitAnd: operator.and_, ast.BitOr: operator.or_, ast.BitXor: operator.xor,
                 ast.FloorDiv: operator.floordiv, ast.Pow: operator.pow,
                 ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt,
                 ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne,
                 ast.And: operator.and_, ast.Or: operator.or_, ast.Not: operator.not_}

    # Parse the expression
    try:
        parsed_expr = ast.parse(expression, mode='eval').body
    except SyntaxError:
        raise ValueError("Invalid expression")

    # Check if all variables in the expression are in the record
    for node in ast.walk(parsed_expr):
        if isinstance(node, ast.Name) and node.id not in record:
            raise ValueError("Invalid variable name in expression")

    # Evaluate the expression
    def _evaluate(node):
        if isinstance(node, ast.Num):  # <number>
            return node.n
        elif isinstance(node, ast.Str):  # <string>
            return node.s
        elif isinstance(node, ast.Name):  # <variable>
            return record[node.id]
        elif isinstance(node, ast.BinOp):  # <left> <operator> <right>
            return operators[type(node.op)](_evaluate(node.left), _evaluate(node.right))
        elif isinstance(node, ast.UnaryOp):  # <operator> <operand> e.g., -1
            return operators[type(node.op)](_evaluate(node.operand))
        elif isinstance(node, ast.Compare):  # <left> <comparators>
            left = _evaluate(node.left)
            for i, op, comparator in zip(range(len(node.comparators)), node.ops, node.comparators):
                if i == 0:
                    result = operators[type(op)](left, _evaluate(comparator))
                else:
                    result = result and operators[type(op)](left, _evaluate(comparator))
            return result
        elif isinstance(node, ast.BoolOp):  # <values>
            values = [_evaluate(value) for value in node.values]
            return operators[type(node.op)](*values)
        else:
            raise ValueError("Invalid expression")

    return _evaluate(parsed_expr)
