def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort jobs in decreasing order of profit
    jobs.sort(key=lambda x: (-x[2], x))

    # Initialize an empty list to store the scheduled jobs
    scheduled_jobs = [None] * max(1, max(job[1] for job in jobs))

    # Schedule jobs
    for job in jobs:
        for i in range(min(job[1], len(scheduled_jobs))):
            if scheduled_jobs[i] is None:
                scheduled_jobs[i] = job[0]
                break

    # Return the scheduled jobs
    return [job for job in scheduled_jobs if job is not None]

