def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    def is_attack(i, j, blocked):
        for b in blocked:
            if b[0] == i or b[1] == j or (b[0]-i) == (b[1]-j) or (b[0]-i) == -(b[1]-j):
                return True
        return False

    def solve(n, i, blocked):
        if i == n:
            return 1
        count = 0
        for j in range(n):
            if not is_attack(i, j, blocked):
                count += solve(n, i+1, blocked)
        return count

    blocked = [(i, j) for i, j in blocked if 0 <= i < n and 0 <= j < n]
    return solve(n, 0, blocked)
