import heapq

def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    graph = {}
    for u, v, w in edges:
        if u not in graph: graph[u] = {}
        if v not in graph: graph[v] = {}
        graph[u][v] = w
        graph[v][u] = w

    queue = [(0, start, [start])]
    seen = set()
    while queue:
        (cost, node, path) = heapq.heappop(queue)
        if node not in seen:
            seen.add(node)
            if node == goal:
                return (cost, path)
            for (next_node, next_cost) in graph[node].items():
                if next_node not in seen:
                    heapq.heappush(queue, (cost + next_cost, next_node, path + [next_node]))
    return None
