import operator
import re

OPERATORS = {'+': (1, operator.add), '-': (1, operator.sub), '*': (2, operator.mul), '/': (2, operator.floordiv), '^': (3, operator.pow)}

def evaluate_expression(expr: str) -> int:
    def parse_token(token: str):
        if token == '-':
            return OPERATORS[token]
        elif token.isdigit():
            return int(token)
        elif token == '(':
            return token
        elif token == ')':
            return token
        else:
            raise ValueError(f"Invalid token: {token}")

    def parse_expr(expr):
        stack = []
        tokens = re.findall(r'\d+|[-+*/()^]|-', expr)
        for token in tokens:
            if token in OPERATORS:
                while stack and stack[-1] != '(' and OPERATORS[token][0] <= OPERATORS[stack[-1]][0]:
                    yield stack.pop()
                stack.append(token)
            elif token == '(':
                stack.append(token)
            elif token == ')':
                while stack and stack[-1] != '(':
                    yield stack.pop()
                stack.pop()
            else:
                yield parse_token(token)
        while stack:
            yield stack.pop()

    return reduce(lambda a, b: b[1][1](a, b[0]), ((parse_token(token), OPERATORS[token]) for token in parse_expr(expr)))
