                if last_op == '-':
                    sub_expr = [-x for x in sub_expr]
                    last_op = None
                stack[-1].extend(sub_expr)
            else:
                if last_op == '-':
                    stack[-1].append(-parse_token(token))
                    last_op = None
                else:
                    stack[-1].append(parse_token(token))
                if token in OPERATORS:
                    last_op = token
        return stack[0]

    def shunting_yard(tokens):
        stack = []
        for token in tokens:
            if token in OPERATORS:
                while stack and stack[-1] in OPERATORS and OPERATORS[token][0] <= OPERATORS[stack[-1]][0]:
