def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = {}
    waiting_orders = []

    for event in events:
        kind, item, quantity = event

        if kind == 'receive':
            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity

            while waiting.get(item, 0) > 0 and stock.get(item, 0) > 0 and quantity > 0:
                waiting[item] -= 1
                stock[item] -= 1
                quantity -= 1

            if waiting.get(item, 0) > 0 and stock.get(item, 0) == 0:
                waiting_orders.append((item, waiting[item]))
                waiting[item] = 0

        elif kind == 'order':
            if item in stock and stock[item] >= quantity:
                stock[item] -= quantity
            elif item in stock and stock[item] < quantity:
                waiting[item] = waiting.get(item, 0) + quantity - stock[item]
                stock[item] = 0
            else:
                waiting[item] = waiting.get(item, 0) + quantity

    stock = {item: quantity for item, quantity in stock.items() if quantity > 0}
    waiting_orders.sort()

    return stock, waiting_orders
