    stack = []
    pc = 0  # Program counter
    instr_count = 0  # Instruction counter

    while pc < len(program):
        if instr_count > 1000:
            raise RuntimeError("Too many instructions executed")

        instr = program[pc].split()
        op = instr[0]

        if op == "PUSH":
            if len(instr) != 2 or not instr[1].lstrip('-').isdigit():
                raise ValueError("Invalid PUSH instruction")
            stack.append(int(instr[1]))

        elif op == "POP":
            if len(stack) == 0:
                raise ValueError("Empty stack")
            stack.pop()

        elif op == "DUP":
            if len(stack) == 0:
                raise ValueError("Empty stack")
            stack.append(stack[-1])

