    stack = []
    pc = 0  # Program counter
    max_instructions = 1000
    while pc < len(program) and max_instructions > 0:
        max_instructions -= 1
        instruction = program[pc]
        if instruction.startswith('PUSH'):
            n = int(instruction.split(' ')[1])
            stack.append(n)
        elif instruction == 'POP':
            if not stack:
                raise ValueError('Stack is empty')
            stack.pop()
        elif instruction == 'DUP':
            if len(stack) < 1:
                raise ValueError('Stack has less than 1 element')
            stack.append(stack[-1])
        elif instruction == 'SWAP':
            if len(stack) < 2:
                raise ValueError('Stack has less than 2 elements')
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction == 'ADD':
            if len(stack) < 2:
                raise ValueError('Stack has less than 2 elements')
            stack.append(stack.pop() + stack.pop())
        elif instruction == 'SUB':
            if len(stack) < 2:
                raise ValueError('Stack has less than 2 elements')
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif instruction == 'MUL':
            if len(stack) < 2:
                raise ValueError('Stack has less than 2 elements')
            stack.append(stack.pop() * stack.pop())
        elif instruction.startswith('JMP'):
            t = int(instruction.split(' ')[1])
            if t < 0 or t >= len(program):
                raise ValueError('Invalid jump target')
            pc = t
            continue
        elif instruction.startswith('JZ'):
            t = int(instruction.split(' ')[1])
            if t < 0 or t >= len(program):
