def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    frozen = {}
    failed = []
    balances_copy = balances.copy()

    for i, op in enumerate(ops):
        op_type, account, *args = op
        amount = args[0] if args else 0

        if account not in balances_copy or \
           amount <= 0 or \
           account in frozen or \
           op_type not in ['deposit', 'withdraw', 'transfer', 'freeze', 'unfreeze']:
            failed.append(i)
            continue

        if op_type == 'deposit':
            balances_copy[account] += amount
        elif op_type == 'withdraw':
            if balances_copy[account] - amount < 0:
                failed.append(i)
                continue
            balances_copy[account] -= amount
        elif op_type == 'transfer':
            target = args[1]
            if account == target or balances_copy[account] - amount - 2 < 0 or target not in balances_copy:
                failed.append(i)
                continue
            balances_copy[account] -= amount + 2
            balances_copy[target] += amount
        elif op_type == 'freeze':
            frozen[account] = True
        elif op_type == 'unfreeze':
            if account not in frozen:
                continue
            del frozen[account]

    return (balances_copy, sorted(failed))
