            if len(stack) < 2:
                raise ValueError("Not enough elements on stack for subtraction")
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif op == 'MUL':
            if len(stack) < 2:
                raise ValueError("Not enough elements on stack for multiplication")
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif op == 'JMP':
            t = int(instruction[1])
            if t >= len(program):
                raise ValueError("Jump target out of bounds")
            ip = t - 1
        elif op == 'JZ':
            if not stack:
                raise ValueError("Stack underflow")
            if stack[-1] == 0:
                t = int(instruction[1])
                if t >= len(program):
                    raise ValueError("Jump target out of bounds")
                ip = t - 1
        elif op == 'HALT':
            break

        ip += 1
        max_instructions -= 1
        if max_instructions <= 0:
            raise RuntimeError("Maximum number of instructions exceeded")

    return stack
